  /**
   * Checks if a node is deeply nested to prevent stack overflow.
   * Used to avoid infinite recursion when processing deeply nested
   * binary operations like ADD(a, ADD(b, ADD(c, ...)))
   */
  private boolean isDeeplyNested(Node node, int maxDepth) {
    if (node == null || maxDepth <= 0) {
      return false;
    }

    // Walk down the right side to see if we have a long chain of same operations
    Node current = node;
    int depth = 0;
    while (current != null && current.getType() == node.getType() && depth < maxDepth) {
      current = current.getLastChild();
      depth++;
    }

    return depth >= maxDepth;
  }
}
